using System.Runtime.InteropServices;

namespace CatalogSvc;

public class ProductCatalog
{
    private readonly Dictionary<string, string> _categories = new(StringComparer.OrdinalIgnoreCase);
    private readonly Dictionary<string, decimal> _prices = new(StringComparer.OrdinalIgnoreCase);

    // Reverse index: category → product codes for O(1) category lookups
    private readonly Dictionary<string, List<string>> _productsByCategory = new(StringComparer.OrdinalIgnoreCase);

    public void AddProduct(string code, string category, decimal price)
    {
        // Remove from old category's reverse index if re-categorizing
        ref var existingCategory = ref CollectionsMarshal.GetValueRefOrAddDefault(_categories, code, out bool existed);
        if (existed && existingCategory is not null)
        {
            if (_productsByCategory.TryGetValue(existingCategory, out var oldList))
                oldList.Remove(code);
        }
        existingCategory = category;

        _prices[code] = price;

        ref var list = ref CollectionsMarshal.GetValueRefOrAddDefault(_productsByCategory, category, out _);
        list ??= new List<string>();
        list.Add(code);
    }

    public string? GetCategory(string code)
        => _categories.TryGetValue(code, out var cat) ? cat : null;

    public decimal GetTotalPrice(IEnumerable<string> codes)
    {
        decimal total = 0m;
        foreach (var code in codes)
        {
            if (_prices.TryGetValue(code, out var price))
                total += price;
        }
        return total;
    }

    // O(1) lookup via reverse index instead of O(n) dictionary scan
    public List<string> GetProductsByCategory(string category)
    {
        if (_productsByCategory.TryGetValue(category, out var products))
            return new List<string>(products);
        return new List<string>();
    }
}

